  for(let i=0;i<3;i++)S.logStrengthSet(st,'sk-push-1',i,0,8,true);st=await save(st);assert.equal(SK.levelOf(st,'push'),0);S.finishWorkout(st);st=await save(st);assert.equal(SK.levelOf(st,'push'),1);assert.equal(st.skills,undefined);const duplicate=structuredClone(st);duplicate.strength.active=null;S.startWorkout(duplicate,day,['sk-push-2']);const saved=await save(duplicate);const alias=structuredClone(saved);alias.strength.active.exercises.push({id:'pushup',sets:[{kg:0,reps:8,done:false}]});await assert.rejects(save(alias),/Samma skill/);const started=structuredClone(saved);SK.setLevel(started,'pull',3,day);const back=await save(started);assert.equal(back.skills.pull.level,3);assert.equal(SK.levelOf(back,'pull'),3);assert.equal(SK.levelOf(back,'push'),1,'Workout progress is kept');const cleared=structuredClone(back);SK.setLevel(cleared,'pull',0,day);assert.equal(SK.levelOf(await save(cleared),'pull'),0);
