 await t.test('friends add each other by code, see stats only after accepting, and outsiders see nothing',async()=>{const [c,d,e]=['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cccccccc-cccc-4ccc-8ccc-cccccccccccc'];await db.exec('reset role');for(const id of [c,d,e])await db.query('insert into auth.users(id) values($1)',[id]);const make=async(id,name,character)=>{await as(id);const s=D.normalizeState(D.blankState(),'2026-11-07T12:00:00Z');s.profile.name=name;if(character)s.profile.character=character;await db.query('select public.save_arc_state_v3($1::jsonb,0)',[JSON.stringify(s)]);return (await db.query('select public.my_friend_code() c')).rows[0].c;};const codeC=await make(c,'Cleo','monk'),codeD=await make(d,'Dag'),codeE=await make(e,'Eli');assert.match(codeC,/^[A-Z0-9]{8}$/);await as(c);assert.equal((await db.query('select public.my_friend_code() c')).rows[0].c,codeC,'The code is stable');await as(d);await assert.rejects(db.query('select public.request_friend($1)',[codeD]),/egen/);await assert.rejects(db.query('select public.request_friend($1)',['ZZZZZZZZ']),/Hittade ingen/);assert.equal((await db.query('select public.request_friend($1) r',[codeC.toLowerCase()])).rows[0].r,'pending');let mine=(await db.query('select * from public.friends_overview()')).rows;assert.equal(mine.length,1);assert.equal(mine[0].relation,'outgoing');assert.equal(mine[0].display_name,'Cleo');assert.equal(mine[0].xp,null,'No stats before accepting');await as(e);assert.equal((await db.query('select * from public.friendships')).rows.length,0);assert.equal((await db.query('select * from public.friends_overview()')).rows.length,0);await assert.rejects(db.query('select public.respond_friend($1,true)',[mine[0].friendship_id]),/finns inte/);await assert.rejects(db.query('select * from public.friend_codes where user_id<>auth.uid()').then(r=>{if(r.rows.length)throw Error('leak');}).then(()=>{throw Error('ok')}),/ok/);await as(c);const incoming=(await db.query('select * from public.friends_overview()')).rows[0];assert.equal(incoming.relation,'incoming');await db.query('select public.respond_friend($1,true)',[incoming.friendship_id]);const friend=(await db.query('select * from public.friends_overview()')).rows[0];assert.equal(friend.relation,'friend');assert.equal(friend.display_name,'Dag');assert.equal(Number(friend.xp),0);assert.equal(friend.training_streak,0);assert.equal(friend.streak,0);await as(d);mine=(await db.query('select * from public.friends_overview()')).rows;assert.equal(mine[0].char_kind,'monk');assert.equal((await db.query('select public.request_friend($1) r',[codeC])).rows[0].r,'accepted');await db.query('select public.remove_friend($1)',[mine[0].friendship_id]);await as(c);assert.equal((await db.query('select * from public.friends_overview()')).rows.length,0);await as(e);await db.query('select public.request_friend($1)',[codeC]);await as(c);assert.equal((await db.query('select public.request_friend($1) r',[codeE])).rows[0].r,'accepted','Adding someone who already asked you accepts it');await assert.rejects(db.query('insert into public.friendships(requester,addressee,status) values($1,$2,$3)',[c,d,'accepted']),/permission/);await as(e);const prof=(await db.query('select * from public.member_profile($1)',[c])).rows[0];assert.equal(prof.relation,'friend');assert.equal(prof.display_name,'Cleo');assert.equal(prof.char_kind,'monk');assert.equal(prof.workouts,0);assert.equal(prof.trained_today,false);assert.equal((await db.query('select * from public.member_profile($1)',[e])).rows[0].relation,'self');await as(d);await assert.rejects(db.query('select * from public.member_profile($1)',[c]),/privat/,'Strangers cannot open a profile');});
 await t.test('squad members add each other as friends from the profile, outsiders cannot',async()=>{const [m1,m2,m3]=['f1f1f1f1-0000-4000-8000-000000000027','f2f2f2f2-0000-4000-8000-000000000027','f3f3f3f3-0000-4000-8000-000000000027'];await db.exec('reset role');for(const [u,n] of [[m1,'Ana'],[m2,'Bo'],[m3,'Cy']]){await db.query('insert into auth.users(id) values($1)',[u]);await db.query('insert into public.profiles(id,display_name) values($1,$2)',[u,n]);}const sq=(await db.query("insert into public.squads(name,created_by) values('Pals',$1) returning id",[m1])).rows[0].id;await db.query('insert into public.squad_members(squad_id,user_id) values($1,$2),($1,$3)',[sq,m1,m2]);await as(m2);assert.equal((await db.query('select public.request_friend_member($1) r',[m1])).rows[0].r,'pending');assert.equal((await db.query('select public.request_friend_member($1) r',[m1])).rows[0].r,'pending','asking twice keeps one request');await assert.rejects(db.query('select public.request_friend_member($1)',[m2]),/dig själv/);await as(m3);await assert.rejects(db.query('select public.request_friend_member($1)',[m1]),/samma squad/);await as(m1);assert.equal((await db.query('select public.request_friend_member($1) r',[m2])).rows[0].r,'accepted','their request is accepted when you add them back');await db.exec('reset role');assert.equal((await db.query("select count(*)::int n from public.friendships where status='accepted' and least(requester,addressee)=least($1::uuid,$2::uuid)",[m1,m2])).rows[0].n,1);});
 await t.test('server and client agree on the new XP rules and keep XP earned before them',async()=>{await db.exec('reset role');const b='2026-11-09',a='2026-11-10';const st=D.normalizeState(D.blankState(b),'2026-11-07T12:00:00Z');const own={id:D.uid(),name:'Gitarr',category:'music',target:1,unit:'gång',cue:'',days:[0,1,2,3,4,5,6],start:b,xp:15,archived:false};st.habits=['Läs en bok','Promenad','Kall avslutning på duschen','Rörlighet','Styrketräning','Löpning'].map(n=>D.makeHabit(D.library.find(h=>h[0]===n),b)).concat(own);for(const d of [b,a])for(const h of st.habits)D.setProgress(st,h.id,h.target,d);D.claimQuest(st,'three:'+b,b);D.claimQuest(st,'three:'+a,a);S.startWorkout(st,b,['bench'],1000);st.strength.active.exercises[0].sets=Array.from({length:6},()=>({kg:40,reps:8,done:true}));S.finishWorkout(st,1000+90*60000);S.startWorkout(st,a,['bench'],9000000);st.strength.active.exercises[0].sets=Array.from({length:6},()=>({kg:40,reps:8,done:true}));S.finishWorkout(st,9000000+90*60000);const sql=async until=>Number((await db.query('select public.arc_total_xp($1::jsonb,$2) n',[JSON.stringify(st),until])).rows[0].n);const legacy=await sql(b);assert.ok(legacy>200,'The day before keeps its old XP');const total=await sql('2026-11-11');assert.equal(total,D.totalXP(st));assert.equal(total-legacy,40+35+25+20+15,'Five activities once each; no quest, combo, own habit or time-based XP');assert.equal(Number((await db.query('select public.arc_rules_day_xp($1::jsonb,$2) n',[JSON.stringify(st),a])).rows[0].n),D.dayTotalXP(st,a));});
 await t.test('warm-up sets save and stay locked, exercises can be reordered and removed, and warm-ups never count as a personal best',async()=>{await db.exec('reset role');const id='abababab-abab-4bab-8bab-abababababab';await db.query('insert into auth.users(id) values($1)',[id]);await db.query("select set_config('request.jwt.claim.sub',$1,false)",[id]);let st=D.normalizeState(D.blankState(),'2026-11-07T12:00:00Z');let rev=0;const save=async x=>{const r=(await db.query('select public.save_arc_state_v3($1::jsonb,$2) result',[JSON.stringify(x),rev])).rows[0].result;rev=Number(r.revision);return r.payload;};st=await save(st);const day=D.dateKey(new Date(),st.timezone);S.startWorkout(st,day,['bench','row','squat'],1);st=await save(st);await db.query("update public.user_states set payload=jsonb_set(payload,'{strength,active,startedAt}',to_jsonb(floor(extract(epoch from clock_timestamp())*1000)-40*60000)) where user_id=$1",[id]);st.strength.active.startedAt=Number((await db.query("select payload#>>'{strength,active,startedAt}' v from public.user_states where user_id=$1",[id])).rows[0].v);assert.equal(S.moveExercise(st,'squat',-1),true);assert.equal(S.moveExercise(st,'bench',-1),false,'The first exercise cannot move up');S.removeExercise(st,'row');st=await save(st);assert.deepEqual(st.strength.active.exercises.map(e=>e.id),['bench','squat']);S.setSetType(st,'bench',0,'warmup');S.logStrengthSet(st,'bench',0,100,5);st.strength.active.exercises[0].sets.push({kg:60,reps:0,done:false});S.logStrengthSet(st,'bench',1,60,5);st=await save(st);st.strength.active.exercises[0].sets.push({kg:60,reps:0,done:false});st=await save(st);assert.equal(S.removeSet(st,'bench',2),'set');assert.equal(S.removeSet(st,'squat',0),'exercise');st=await save(st);assert.equal(st.strength.active.exercises[0].sets.length,2,'A removed set is saved');assert.deepEqual(st.strength.active.exercises.map(e=>e.id),['bench']);assert.equal(st.strength.active.exercises[0].sets[0].type,'warmup');const w0={...st.strength.active,finishedAt:1};assert.equal(Math.round(S.bestSet(w0,'bench')),Math.round(S.e1rm(60,5)),'The heavier warm-up is not a personal best');S.finishWorkout(st);st=await save(st);assert.equal(st.strength.sessions.at(-1).exercises[0].sets[0].type,'warmup');st=await save(st);const changed=structuredClone(st);changed.strength.sessions.at(-1).exercises[0].sets[0].type='failure';await assert.rejects(save(changed),/låsta/);const bad=structuredClone(st);S.startWorkout(bad,day,['deadlift'],1);bad.strength.active.exercises[0].sets[0].type='cooldown';await assert.rejects(save(bad),/settyp/i);});
